import os
import tarfile
import re
import json
import requests
import logging
import random
import time
import shutil
import glob
import mmap
from pathlib import Path
from dataclasses import dataclass
from typing import List, Optional, Dict, Any
from datetime import datetime

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
logger = logging.getLogger("sysdiagnose_airdrop_grok")

XAI_API_KEY = os.getenv("XAI_API_KEY")
if not XAI_API_KEY:
    raise RuntimeError("XAI_API_KEY environment variable is required")

XAI_BASE_URL = ""
XAI_CHAT_COMPLETIONS_PATH = "/v1/chat/completions"
XAI_LIST_MODELS_PATH = "/v1/models"
MODEL_NAME = "grok-4-1-fast-reasoning"

ALLOWED_SUFFIXES = {".log", ".txt", ".ips", ".plist", ".crash", ".logarchive"}
AIRDROP_TERMS = [
    "airdrop",
    "sharingd",
    "sharinguiservice",
    "com.apple.sharing",
    "awdl",
    "awdl0",
    "nearby",
    "nearbyinteraction",
    "nearbyservice",
    "multipeer",
    "mcsession",
    "bonjour",
    "nsnetservice",
    "sharingdaemon",
    "sharing",
    "receiver",
    "sender",
    "advertise",
    "advertisement",
    "discover",
    "discovery",
    "session",
    "transfer",
    "export",
    "send",
    "sent",
    "receive",
    "received",
    "accept",
    "accepted",
    "decline",
    "denied",
    "file",
    "photo",
    "image",
    ".jpg",
    ".jpeg",
    ".png",
    ".heic",
    ".mov",
    ".pdf",
    ".doc",
    ".docx",
    ".zip"
]

SEND_REGEXES = [
    re.compile(r"\b(sent|send|sending|outgoing|export|transfer|sharing)\b", re.IGNORECASE),
    re.compile(r"\b(airdrop)\b.*\b(sent|send|sending|outgoing|export|transfer)\b", re.IGNORECASE),
    re.compile(r"\b(sharingd)\b.*\b(sent|send|sending|outgoing|export|transfer)\b", re.IGNORECASE)
]

RECEIVE_REGEXES = [
    re.compile(r"\b(received|receive|incoming|accepted|accept)\b", re.IGNORECASE),
    re.compile(r"\b(airdrop)\b.*\b(received|receive|incoming|accepted|accept)\b", re.IGNORECASE),
    re.compile(r"\b(sharingd)\b.*\b(received|receive|incoming|accepted|accept)\b", re.IGNORECASE)
]

TIMESTAMP_REGEXES = [
    re.compile(r"(\d{4}-\d{2}-\d{2}[T\s]\d{2}:\d{2}:\d{2}(?:\.\d+)?)"),
    re.compile(r"([A-Z][a-z]{2}\s+\d{1,2}\s+\d{2}:\d{2}:\d{2}(?:\.\d+)?)")
]

def _now_tag() -> str:
    return datetime.now().strftime("%Y%m%d_%H%M%S")

def _safe_relpath(p: Path, root: Path) -> str:
    try:
        return str(p.relative_to(root))
    except Exception:
        return str(p)

def _is_within_directory(directory: Path, target: Path) -> bool:
    try:
        directory_resolved = directory.resolve()
        target_resolved = target.resolve()
        return str(target_resolved).startswith(str(directory_resolved))
    except Exception:
        return False

def safe_extract_tar(tar_path: Path, extract_dir: Path) -> None:
    extract_dir.mkdir(parents=True, exist_ok=True)
    with tarfile.open(tar_path, "r:*") as tar:
        members = tar.getmembers()
        for m in members:
            name = m.name
            if not name or name == ".":
                continue
            if name.startswith("/") or name.startswith("\\"):
                continue
            if ".." in Path(name).parts:
                continue
            dest_path = (extract_dir / name)
            if not _is_within_directory(extract_dir, dest_path):
                continue
            try:
                if m.isdir():
                    dest_path.mkdir(parents=True, exist_ok=True)
                elif m.isfile():
                    dest_path.parent.mkdir(parents=True, exist_ok=True)
                    f = tar.extractfile(m)
                    if f is None:
                        continue
                    with open(dest_path, "wb") as out:
                        shutil.copyfileobj(f, out, length=1024 * 1024)
                    try:
                        os.chmod(dest_path, 0o600)
                    except Exception:
                        pass
            except Exception:
                continue

def find_sysdiagnose_tar_gz() -> Path:
    candidates: List[Path] = []
    for p in Path(".").rglob("*.tar.gz"):
        if p.is_file() and ("sysdiagnose" in p.name.lower() or p.name.lower() == "1.tar.gz"):
            candidates.append(p)
    if not candidates:
        raise RuntimeError("No sysdiagnose tar.gz found (expected sysdiagnose*.tar.gz or 1.tar.gz)")
    candidates.sort(key=lambda x: x.stat().st_mtime, reverse=True)
    return candidates[0]

def find_extracted_root(extract_dir: Path) -> Path:
    if not extract_dir.exists():
        raise RuntimeError("Extract directory does not exist")
    dirs = [d for d in extract_dir.iterdir() if d.is_dir()]
    if len(dirs) == 1:
        return dirs[0]
    return extract_dir

def _line_has_terms(line_lower: str) -> bool:
    for t in AIRDROP_TERMS:
        if t in line_lower:
            return True
    return False

def _classify_line(line: str) -> str:
    for r in SEND_REGEXES:
        if r.search(line):
            return "SEND"
    for r in RECEIVE_REGEXES:
        if r.search(line):
            return "RECEIVE"
    return "OTHER"

def _extract_timestamp(line: str) -> Optional[str]:
    for rx in TIMESTAMP_REGEXES:
        m = rx.search(line)
        if m:
            return m.group(1)
    return None

@dataclass
class Event:
    file: str
    line_number: int
    timestamp: Optional[str]
    type: str
    line: str

def iter_text_lines_fast(file_path: Path) -> List[str]:
    try:
        size = file_path.stat().st_size
    except Exception:
        return []
    if size == 0:
        return []
    if size > 512 * 1024 * 1024:
        return []
    try:
        with open(file_path, "rb") as f:
            mm = mmap.mmap(f.fileno(), 0, access=mmap.ACCESS_READ)
            try:
                data = mm.read().decode("utf-8", errors="ignore")
            finally:
                mm.close()
        return data.splitlines()
    except Exception:
        return []

def collect_events(extracted_root: Path, max_events: int) -> List[Event]:
    events: List[Event] = []
    for fp in extracted_root.rglob("*"):
        if not fp.is_file():
            continue
        if fp.suffix.lower() not in ALLOWED_SUFFIXES:
            continue
        lines = iter_text_lines_fast(fp)
        if not lines:
            continue
        rel = _safe_relpath(fp, extracted_root)
        for idx, line in enumerate(lines, 1):
            ll = line.lower()
            if not _line_has_terms(ll):
                continue
            etype = _classify_line(line)
            ts = _extract_timestamp(line)
            events.append(Event(file=rel, line_number=idx, timestamp=ts, type=etype, line=line.strip()))
            if len(events) >= max_events:
                return events
    return events

def summarize_locally(events: List[Event]) -> Dict[str, Any]:
    send_events = [e for e in events if e.type == "SEND"]
    receive_events = [e for e in events if e.type == "RECEIVE"]
    other_events = [e for e in events if e.type == "OTHER"]
    files_with_events = sorted({e.file for e in events})
    suspect_send = []
    for e in send_events:
        l = e.line.lower()
        if any(ext in l for ext in [".jpg", ".jpeg", ".png", ".heic", ".mov", ".pdf", ".doc", ".docx", ".zip"]):
            suspect_send.append(e)
    recent = []
    for e in events:
        recent.append({
            "file": e.file,
            "line_number": e.line_number,
            "timestamp": e.timestamp,
            "type": e.type,
            "line": e.line
        })
    return {
        "total_events": len(events),
        "send_events": len(send_events),
        "receive_events": len(receive_events),
        "other_events": len(other_events),
        "files_with_events_count": len(files_with_events),
        "files_with_events": files_with_events[:200],
        "suspect_send_count": len(suspect_send),
        "suspect_send_samples": [
            {"file": e.file, "line_number": e.line_number, "timestamp": e.timestamp, "line": e.line}
            for e in suspect_send[:200]
        ],
        "recent_events": recent[:2000]
    }

def xai_list_models() -> List[Dict[str, Any]]:
    headers = {"Authorization": f"Bearer {XAI_API_KEY}"}
    url = f"{XAI_BASE_URL}{XAI_LIST_MODELS_PATH}"
    r = requests.get(url, headers=headers, timeout=(5, 30))
    r.raise_for_status()
    data = r.json()
    if isinstance(data, dict) and "data" in data and isinstance(data["data"], list):
        return data["data"]
    if isinstance(data, list):
        return data
    return []

def xai_chat(prompt: str, max_tokens: int) -> str:
    headers = {"Authorization": f"Bearer {XAI_API_KEY}", "Content-Type": "application/json"}
    url = f"{XAI_BASE_URL}{XAI_CHAT_COMPLETIONS_PATH}"
    payload = {
        "model": MODEL_NAME,
        "messages": [{"role": "user", "content": prompt}],
        "temperature": 0.1,
        "max_tokens": max_tokens,
        "stream": False
    }
    last_err = None
    for attempt in range(5):
        try:
            r = requests.post(url, headers=headers, json=payload, timeout=(5, 120))
            r.raise_for_status()
            j = r.json()
            if not isinstance(j, dict):
                raise RuntimeError("Invalid JSON response (not dict)")
            choices = j.get("choices")
            if not isinstance(choices, list) or not choices:
                raise RuntimeError("Invalid JSON response (missing choices)")
            msg = choices[0].get("message")
            if not isinstance(msg, dict):
                raise RuntimeError("Invalid JSON response (missing message)")
            content = msg.get("content")
            if not isinstance(content, str):
                raise RuntimeError("Invalid JSON response (missing content)")
            return content
        except Exception as e:
            last_err = e
            time.sleep((2 ** attempt) + random.uniform(0.0, 1.0))
    raise RuntimeError(f"xAI request failed: {last_err}")

def build_prompt(local_summary: Dict[str, Any]) -> str:
    return (
        "Magyarul elemezd ezt az iOS sysdiagnose kivonatot AirDrop szempontból.\n"
        "Feladat:\n"
        "1) Mondd meg, van-e bizonyíték kimenő (SEND) AirDrop fájlküldésre.\n"
        "2) Emeld ki a leggyanúsabb küldéseket (fájlkiterjesztés/fájlnév, ha van).\n"
        "3) Írj rövid, technikai pontosságú magyarázatot arról, hogy ezek mit jelentenek.\n"
        "4) Adj konkrét teendőlistát iPhone-on a biztonság növelésére.\n"
        "Kimenet: tömör, jól tagolt magyar szöveg.\n\n"
        f"ADATOK (JSON):\n{json.dumps(local_summary, ensure_ascii=False)}\n"
    )

def write_text(path: Path, text: str) -> None:
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)

def write_events_txt(path: Path, events: List[Event]) -> None:
    with open(path, "w", encoding="utf-8") as f:
        for e in events:
            ts = e.timestamp if e.timestamp is not None else "NO_TIMESTAMP"
            f.write(f"[{e.type}] {ts} | {e.file}:{e.line_number}\n")
            f.write(f"{e.line}\n\n")

def main() -> None:
    tar_path = find_sysdiagnose_tar_gz()
    out_dir = Path(f"OUTPUT_{_now_tag()}")
    out_dir.mkdir(parents=True, exist_ok=True)
    extract_dir = out_dir / "extracted"
    if extract_dir.exists():
        shutil.rmtree(extract_dir)
    extract_dir.mkdir(parents=True, exist_ok=True)
    safe_extract_tar(tar_path, extract_dir)
    extracted_root = find_extracted_root(extract_dir)
    events = collect_events(extracted_root, max_events=200000)
    write_events_txt(out_dir / "1_EVENTS_ALL.txt", events)
    send_events = [e for e in events if e.type == "SEND"]
    recv_events = [e for e in events if e.type == "RECEIVE"]
    write_events_txt(out_dir / "2_EVENTS_SEND.txt", send_events)
    write_events_txt(out_dir / "3_EVENTS_RECEIVE.txt", recv_events)
    local_summary = summarize_locally(events)
    write_text(out_dir / "4_LOCAL_SUMMARY.json", json.dumps(local_summary, ensure_ascii=False, indent=2))
    models = []
    try:
        models = xai_list_models()
    except Exception:
        models = []
    write_text(out_dir / "5_XAI_MODELS.json", json.dumps(models, ensure_ascii=False, indent=2))
    prompt = build_prompt(local_summary)
    analysis = xai_chat(prompt, max_tokens=8000)
    write_text(out_dir / "6_GROK_SUMMARY_HU.txt", analysis)

if __name__ == "__main__":
    main()
