XAI_TIMEOUT_CONNECT = float(os.getenv("XAI_TIMEOUT_CONNECT", "10"))
XAI_TIMEOUT_READ = float(os.getenv("XAI_TIMEOUT_READ", "240"))

IPV4_RE = re.compile(r"\b(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b")
DOMAIN_RE = re.compile(r"\b(?:[a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}\b")
URL_RE = re.compile(r"\bhttps?://[^\s<>\"]+\b")

SEND_HINT_RE = re.compile(r"\b(sent|send|sending|outgoing|export|transfer)\b", re.IGNORECASE)
RECEIVE_HINT_RE = re.compile(r"\b(received|receive|incoming|accepted|accept)\b", re.IGNORECASE)

TS_RE_LIST = [
    re.compile(r"(\d{4}-\d{2}-\d{2}[T\s]\d{2}:\d{2}:\d{2}(?:\.\d+)?)"),
    re.compile(r"\b([A-Z][a-z]{2}\s+\d{1,2}\s+\d{2}:\d{2}:\d{2}(?:\.\d+)?)\b")
]

def now_tag() -> str:
    return datetime.now().strftime("%Y%m%d_%H%M%S")

def safe_mkdir(p: Path) -> None:
    p.mkdir(parents=True, exist_ok=True)

def sha256_file(p: Path, chunk: int = 1024 * 1024) -> str:
    h = hashlib.sha256()
    with open(p, "rb") as f:
        while True:
            b = f.read(chunk)
            if not b:
                break
            h.update(b)
    return h.hexdigest()

def human_bytes(n: int) -> str:
    if n < 0:
        return str(n)
    units = ["B", "KB", "MB", "GB", "TB", "PB"]
    if n == 0:
        return "0B"
    k = 1024.0
    i = min(int(math.floor(math.log(n, k))), len(units) - 1)
    v = n / (k ** i)
    if v >= 100:
        return f"{v:.0f}{units[i]}"
    if v >= 10:
        return f"{v:.1f}{units[i]}"
    return f"{v:.2f}{units[i]}"

def relpath_str(p: Path, root: Path) -> str:
    try:
        return str(p.relative_to(root))
    except Exception:
        return str(p)

def find_extracted_root() -> Path:
    cwd = Path(".").resolve()
    candidates: List[Path] = []
    for p in cwd.iterdir():
        if p.is_dir():
            name = p.name.lower()
            if name.startswith("sysdiagnose_") or name in {"extracted_logs", "extracted_logs_safe", "extracted_logs_0", "extracted_logs_1"}:
                candidates.append(p)
    if candidates:
        candidates.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        return candidates[0]
    deep = list(cwd.rglob("sysdiagnose_*"))
    deep = [d for d in deep if d.is_dir()]
    if deep:
        deep.sort(key=lambda x: x.stat().st_mtime, reverse=True)
        return deep[0]
    tar_candidates = []
    for t in cwd.rglob("*.tar.gz"):
        if t.is_file() and ("sysdiagnose" in t.name.lower() or t.name.lower() == "1.tar.gz"):
            tar_candidates.append(t)
    if not tar_candidates:
        raise RuntimeError("Nem található kibontott sysdiagnose mappa és tar.gz sem.")
    tar_candidates.sort(key=lambda x: x.stat().st_mtime, reverse=True)
    tar_path = tar_candidates[0]
    extract_dir = cwd / f"extracted_{now_tag()}"
    safe_mkdir(extract_dir)
    with tarfile.open(tar_path, "r:*") as tar:
        tar.extractall(extract_dir)
    subdirs = [d for d in extract_dir.iterdir() if d.is_dir()]
    if len(subdirs) == 1:
        return subdirs[0]
    return extract_dir

def iter_files(root: Path) -> Iterable[Path]:
    for p in root.rglob("*"):
        if p.is_file():
            yield p

def looks_text_by_suffix(p: Path) -> bool:
    s = p.suffix.lower()
    if s in TEXT_SUFFIX_ALLOW:
        return True
    if s in BINARY_SUFFIX_ALLOW:
        return False
    if s == "":
        return p.stat().st_size <= 16 * 1024 * 1024
    return p.stat().st_size <= 8 * 1024 * 1024

def normalize_lower(s: str) -> str:
    return s.lower()

def extract_timestamp(line: str) -> Optional[str]:
    for rx in TS_RE_LIST:
        m = rx.search(line)
        if m:
            return m.group(1)
    return None

def classify_send_receive(line: str) -> str:
    if SEND_HINT_RE.search(line) and not RECEIVE_HINT_RE.search(line):
        return "SEND"
    if RECEIVE_HINT_RE.search(line) and not SEND_HINT_RE.search(line):
        return "RECEIVE"
    if SEND_HINT_RE.search(line) and RECEIVE_HINT_RE.search(line):
        return "BOTH"
    return "OTHER"

def stream_text_hits(path: Path, root: Path, term_groups: Dict[str, List[str]], max_bytes: int, max_sample_lines_per_group: int) -> Tuple[Dict[str, int], Dict[str, List[Dict[str, Any]]], Dict[str, Any]]:
    counts: Dict[str, int] = {k: 0 for k in term_groups.keys()}
    samples: Dict[str, List[Dict[str, Any]]] = {k: [] for k in term_groups.keys()}
    meta: Dict[str, Any] = {
        "first_ts": None,
        "last_ts": None,
        "send_receive": {"SEND": 0, "RECEIVE": 0, "BOTH": 0, "OTHER": 0},
        "ips": {},
        "domains": {},
        "urls": {}
    }
    size = path.stat().st_size
    read_limit = min(size, max_bytes)
    rel = relpath_str(path, root)
    try:
        with open(path, "rb") as f:
            buf = b""
            read_total = 0
            line_num = 0
            while read_total < read_limit:
                chunk = f.read(min(1024 * 1024, read_limit - read_total))
                if not chunk:
                    break
                read_total += len(chunk)
                buf += chunk
                while True:
                    nl = buf.find(b"\n")
                    if nl < 0:
                        if len(buf) > 16 * 1024 * 1024:
                            buf = buf[-4096:]
                        break
                    raw_line = buf[:nl + 1]
                    buf = buf[nl + 1:]
                    line_num += 1
                    try:
                        line = raw_line.decode("utf-8", errors="ignore").rstrip("\r\n")
                    except Exception:
                        line = ""
                    if not line:
                        continue
                    ts = extract_timestamp(line)
                    if ts is not None:
                        if meta["first_ts"] is None:
                            meta["first_ts"] = ts
                        meta["last_ts"] = ts
                    sr = classify_send_receive(line)
                    meta["send_receive"][sr] = meta["send_receive"].get(sr, 0) + 1
                    l = normalize_lower(line)
                    for ip in IPV4_RE.findall(line):
                        meta["ips"][ip] = meta["ips"].get(ip, 0) + 1
                    for u in URL_RE.findall(line):
                        meta["urls"][u] = meta["urls"].get(u, 0) + 1
                    for d in DOMAIN_RE.findall(line):
                        if "." in d and not d.endswith(".local"):
                            meta["domains"][d] = meta["domains"].get(d, 0) + 1
                    for group, terms in term_groups.items():
                        hit = False
                        for t in terms:
                            if t in l:
                                hit = True
                                break
                        if hit:
                            counts[group] += 1
                            if len(samples[group]) < max_sample_lines_per_group:
                                samples[group].append({
                                    "file": rel,
                                    "line_number": line_num,
                                    "timestamp": ts,
                                    "send_receive": sr,
                                    "line": line
                                })
    except Exception:
        return counts, samples, meta
    return counts, samples, meta

def iter_ascii_strings_from_bytes(data: bytes, min_len: int) -> Iterable[str]:
    acc = bytearray()
    for b in data:
        if 32 <= b <= 126:
            acc.append(b)
        else:
            if len(acc) >= min_len:
                yield acc.decode("ascii", errors="ignore")
            acc.clear()
    if len(acc) >= min_len:
        yield acc.decode("ascii", errors="ignore")

def binary_strings_hits(path: Path, root: Path, term_groups: Dict[str, List[str]], max_bytes: int, min_ascii_len: int, max_sample_strings_per_group: int) -> Tuple[Dict[str, int], Dict[str, List[Dict[str, Any]]]]:
    counts: Dict[str, int] = {k: 0 for k in term_groups.keys()}
    samples: Dict[str, List[Dict[str, Any]]] = {k: [] for k in term_groups.keys()}
    size = path.stat().st_size
    read_limit = min(size, max_bytes)
    rel = relpath_str(path, root)
    try:
        with open(path, "rb") as f:
            mm = mmap.mmap(f.fileno(), 0, access=mmap.ACCESS_READ)
            try:
                data = mm[:read_limit]
            finally:
                mm.close()
        for s in iter_ascii_strings_from_bytes(data, min_ascii_len):
            sl = normalize_lower(s)
            for group, terms in term_groups.items():
                hit = False
                for t in terms:
                    if t in sl:
                        hit = True
                        break
                if hit:
                    counts[group] += 1
                    if len(samples[group]) < max_sample_strings_per_group:
                        samples[group].append({"file": rel, "string": s})
    except Exception:
        return counts, samples
    return counts, samples

def write_csv(path: Path, header: List[str], rows: List[List[Any]]) -> None:
