def xai_chat(messages: List[Dict[str, str]], max_tokens: int) -> Optional[str]:
    if not XAI_API_KEY:
        return None
    url = f"{XAI_BASE_URL}/chat/completions"
    headers = {"Authorization": f"Bearer {XAI_API_KEY}", "Content-Type": "application/json"}
    payload = {
        "model": XAI_MODEL,
        "messages": messages,
        "temperature": 0.1,
        "max_tokens": max_tokens,
        "stream": False
    }
    last_err: Optional[str] = None
    for attempt in range(6):
        try:
            r = requests.post(url, headers=headers, json=payload, timeout=(XAI_TIMEOUT_CONNECT, XAI_TIMEOUT_READ))
            if r.status_code >= 400:
                last_err = f"{r.status_code} {r.text}"
                time.sleep((2 ** attempt) + random.uniform(0.0, 1.0))
                continue
            j = r.json()
            ch = j.get("choices")
            if not isinstance(ch, list) or not ch:
                last_err = "missing choices"
                time.sleep((2 ** attempt) + random.uniform(0.0, 1.0))
                continue
            msg = ch[0].get("message")
            if not isinstance(msg, dict):
                last_err = "missing message"
                time.sleep((2 ** attempt) + random.uniform(0.0, 1.0))
                continue
            c = msg.get("content")
            if not isinstance(c, str):
                last_err = "missing content"
                time.sleep((2 ** attempt) + random.uniform(0.0, 1.0))
                continue
            return c
        except Exception as e:
            last_err = str(e)
            time.sleep((2 ** attempt) + random.uniform(0.0, 1.0))
    return f"xAI API hiba: {last_err}"

def build_hu_llm_prompt(global_summary: Dict[str, Any], group_summaries: Dict[str, Any], top_samples: Dict[str, List[Dict[str, Any]]]) -> List[Dict[str, str]]:
