    "repo", "apt", "dpkg", "opainstaller", "bfdecrypt", "steaks4uce",
    "ping", "traceroute", "netstat", "tcpdump", "wireshark", "mitmproxy",
    "burp", "charles", "proxyman", "shadowsocks", "v2ray", "trojan", "wireguard",
