]

def build_terms_regex(terms: List[str]) -> re.Pattern:
    uniq = sorted(set(t.lower() for t in terms), key=len, reverse=True)
    parts = [re.escape(t) for t in uniq if t]
    if not parts:
        return re.compile(r'^(?!)$')
    return re.compile(r'(' + '|'.join(parts) + r')', re.IGNORECASE)

TERMS_RE = build_terms_regex(SURVEILLANCE_TERMS)

