def safe_mkdir(path: Path) -> None:
    path.mkdir(parents=True, exist_ok=True)

def atomic_write_bytes(path: Path, data: bytes) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    with open(tmp, "wb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)

def write_json(path: Path, obj: Any) -> None:
    atomic_write_bytes(path, json.dumps(obj, ensure_ascii=False, indent=2, sort_keys=False).encode("utf-8"))

def write_txt(path: Path, text: str) -> None:
    atomic_write_bytes(path, text.encode("utf-8"))

def now_ts() -> str:
    return datetime.now().strftime("%Y%m%d_%H%M%S")

def sha256_hex(data: Union[str, bytes]) -> str:
    h = hashlib.sha256()
    if isinstance(data, str):
        data = data.encode("utf-8", errors="replace")
    h.update(data)
    return h.hexdigest()

def luhn_checksum_ok(digits: str) -> bool:
    s = 0
    alt = False
    for ch in reversed(digits):
        if not ch.isdigit():
            return False
        d = ord(ch) - 48
        if alt:
            d *= 2
            if d > 9:
                d -= 9
        s += d
        alt = not alt
    return s % 10 == 0

def normalize_domain(d: str) -> str:
    return d.strip().strip(".").lower()

def valid_ipv4(s: str) -> bool:
    parts = s.split(".")
    if len(parts) != 4:
        return False
    try:
        for p in parts:
            if p == "":
                return False
            n = int(p)
            if n < 0 or n > 255:
                return False
        return True
    except Exception:
        return False

def normalize_ip(s: str) -> Optional[str]:
    s = s.strip()
    try:
        ip = ipaddress.ip_address(s)
        return str(ip)
    except Exception:
        if valid_ipv4(s):
            return s
        return None

def extract_timestamp(line: str) -> Optional[str]:
    m = ISO_TS_RE.search(line)
    if m:
        return m.group(1)
    m = YMD_HMS_RE.search(line)
    if m:
        txt = m.group(1)
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(txt, fmt).isoformat()
            except Exception:
                pass
        return txt
    m = SYSLOG_TS_RE.search(line)
    if m:
        s = m.group(1)
        try:
            return datetime.strptime(f"{datetime.now().year} {s}", "%Y %b %d %H:%M:%S").isoformat()
        except Exception:
            return s
    return None

def guess_file_type(path: Path) -> Tuple[str, str]:
    suf = path.suffix.lower()
    name = path.name.lower()
    if suf in {".plist", ".mobileconfig"}:
        return ("plist", "config")
    if suf in {".db", ".sqlite", ".sqlite3"}:
        return ("sqlite", "database")
    if suf in {".logarchive"} or name.endswith(".logarchive"):
        return ("logarchive", "log")
    if suf in {".json"}:
        return ("json", "text")
    if suf in {".txt", ".log"}:
        return ("text", "text")
    if suf in {".gz", ".tgz"}:
        return ("gzip", "archive")
    if suf in {".tar"}:
        return ("tar", "archive")
    if suf in {".zip"}:
        return ("zip", "archive")
    return ("unknown", "unknown")

class IOCStore:
    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._store: Dict[Tuple[str, str], IOCRecord] = {}

    def add(self, ioc_type: str, value: str, file_path: str, ts: Optional[str]) -> None:
        key = (ioc_type, value)
        with self._lock:
            rec = self._store.get(key)
            if rec is None:
                rec = IOCRecord(type=ioc_type, value=value, count=0, files=[], first_seen=ts, last_seen=ts)
                self._store[key] = rec
            rec.count += 1
            if file_path not in rec.files:
                rec.files.append(file_path)
            if ts:
                if rec.first_seen is None:
                    rec.first_seen = ts
                rec.last_seen = ts

    def to_list(self) -> List[Dict[str, Any]]:
        with self._lock:
            items = list(self._store.values())
        items.sort(key=lambda r: (r.type, -r.count, r.value))
        return [asdict(r) for r in items]

class EventWriter:
    def __init__(self, out_dir: Path) -> None:
        self.out_dir = out_dir
        safe_mkdir(out_dir)
        self._lock = threading.Lock()
        self._fh_events = open(out_dir / "events.jsonl", "ab", buffering=0)
        self._fh_by_cat: Dict[str, Any] = {}
        self.counts: Dict[str, int] = {}
        self.total_events = 0

    def _fh_for_category(self, cat: str) -> Any:
        key = cat.upper()
        fh = self._fh_by_cat.get(key)
        if fh is None:
            fh = open(self.out_dir / f"events_{key}.jsonl", "ab", buffering=0)
            self._fh_by_cat[key] = fh
        return fh

    def write_event(self, event: ForensicEvent) -> None:
        b = (json.dumps(asdict(event), ensure_ascii=False) + "\n").encode("utf-8")
        with self._lock:
            self._fh_events.write(b)
            self._fh_for_category(event.category).write(b)
            self.total_events += 1
            self.counts[event.category] = self.counts.get(event.category, 0) + 1

    def close(self) -> None:
        with self._lock:
            try:
                self._fh_events.close()
            except Exception:
                pass
            for fh in self._fh_by_cat.values():
                try:
                    fh.close()
                except Exception:
                    pass
            self._fh_by_cat.clear()

class InventoryWriter:
    def __init__(self, out_dir: Path) -> None:
        self.out_dir = out_dir
        safe_mkdir(out_dir)
        self._lock = threading.Lock()
        self._fh = open(out_dir / "inventory.jsonl", "ab", buffering=0)
        self.total_files = 0

    def write_meta(self, meta: FileMetadata) -> None:
        b = (json.dumps(asdict(meta), ensure_ascii=False) + "\n").encode("utf-8")
        with self._lock:
            self._fh.write(b)
            self.total_files += 1

    def close(self) -> None:
        with self._lock:
            try:
                self._fh.close()
            except Exception:
                pass

class EntropyCalculator:
    def __init__(self) -> None:
        self.counts = [0] * 256
        self.total = 0

    def update(self, data: bytes) -> None:
        self.total += len(data)
        for b in data:
            self.counts[b] += 1

    def entropy(self) -> float:
        if self.total == 0:
            return 0.0
        ent = 0.0
        inv_total = 1.0 / float(self.total)
        for c in self.counts:
            if c:
                p = c * inv_total
                ent -= p * math.log2(p)
        return ent

class FileHasher:
    def __init__(self) -> None:
        self.h = hashlib.sha256()

    def update(self, data: bytes) -> None:
        self.h.update(data)

    def hexdigest(self) -> str:
        return self.h.hexdigest()

class TextLineStream:
    def __init__(self, file_obj: Any, encoding: str) -> None:
        self.decoder = codecs.getincrementaldecoder(encoding)(errors="replace")
        self.file_obj = file_obj
        self.buf = ""
        self.eof = False

    def __iter__(self) -> Iterable[str]:
        while True:
            if self.eof and not self.buf:
                return
            chunk = self.file_obj.read(1024 * 1024)
            if not chunk:
                self.eof = True
                text = self.decoder.decode(b"", final=True)
            else:
                text = self.decoder.decode(chunk, final=False)
            if text:
                self.buf += text
            while True:
                idx = self.buf.find("\n")
                if idx < 0:
                    break
                line = self.buf[:idx]
                self.buf = self.buf[idx + 1:]
                yield line
            if self.eof:
                if self.buf:
                    yield self.buf
                    self.buf = ""
                return

class ForensicAnalyzer:
    def __init__(
        self,
        root_path: Path,
        output_path: Path,
        max_workers: int,
        follow_symlinks: bool,
        scan_binary_strings: bool,
        max_binary_strings_bytes: Optional[int],
    ) -> None:
        self.root = root_path.resolve()
        self.output = output_path.resolve()
        safe_mkdir(self.output)
        self.max_workers = max_workers
        self.follow_symlinks = follow_symlinks
        self.scan_binary_strings = scan_binary_strings
        self.max_binary_strings_bytes = max_binary_strings_bytes
        self.iocs = IOCStore()
        self.events_writer = EventWriter(self.output)
        self.inventory_writer = InventoryWriter(self.output)
        self._stop = threading.Event()
        self._files_lock = threading.Lock()
        self._files_scanned = 0
        self._start_time = time.time()

    def stop(self) -> None:
        self._stop.set()

    def _safe_rel(self, p: Path) -> str:
        try:
            return str(p.relative_to(self.root))
        except Exception:
            return str(p)

    def _stat_times(self, st: os.stat_result) -> Tuple[Optional[str], Optional[str], Optional[str]]:
        created = None
        try:
            if hasattr(st, "st_birthtime"):
                created = datetime.fromtimestamp(getattr(st, "st_birthtime")).isoformat()
        except Exception:
            created = None
        modified = None
        accessed = None
        try:
            modified = datetime.fromtimestamp(st.st_mtime).isoformat()
        except Exception:
            modified = None
        try:
            accessed = datetime.fromtimestamp(st.st_atime).isoformat()
        except Exception:
            accessed = None
        return created, modified, accessed

    def _classify_mime(self, entropy: float) -> str:
        if entropy > 7.8:
            return "encrypted_or_compressed"
        if entropy > 6.8:
            return "binary"
        return "text"

    def _build_event(
        self,
        timestamp: Optional[str],
        category: str,
        subcategory: str,
        file_path: str,
        line_offset: int,
        raw_line: str,
        normalized_line: str,
        severity: str,
        iocs: Dict[str, Any],
        file_sha256: str,
        file_entropy: float,
    ) -> ForensicEvent:
        eid_src = f"{timestamp or ''}|{category}|{subcategory}|{file_path}|{line_offset}|{raw_line}"
        event_id = sha256_hex(eid_src)
        return ForensicEvent(
            timestamp=timestamp,
            category=category,
            subcategory=subcategory,
            file_path=file_path,
            line_offset=line_offset,
            raw_line=raw_line,
            normalized_line=normalized_line,
            severity=severity,
            iocs=iocs,
            file_sha256=file_sha256,
            file_entropy=file_entropy,
            event_id=event_id,
        )

    def _emit_event(self, event: ForensicEvent) -> None:
        self.events_writer.write_event(event)
        ts = event.timestamp
        fp = event.file_path
        for k, v in event.iocs.items():
            if v is None:
                continue
            if isinstance(v, str):
                self.iocs.add(k, v, fp, ts)
            elif isinstance(v, (int, float, bool)):
                self.iocs.add(k, str(v), fp, ts)
            elif isinstance(v, list):
                for item in v:
                    if item is None:
                        continue
                    self.iocs.add(k, str(item), fp, ts)
            else:
                self.iocs.add(k, json.dumps(v, ensure_ascii=False, sort_keys=True), fp, ts)

    def _scan_text_line(self, file_rel: str, file_sha: str, file_ent: float, line_num: int, line: str) -> None:
        line_stripped = line.rstrip("\r")
        line_lower = line_stripped.lower()
        ts = extract_timestamp(line_stripped)

        m_term = TERMS_RE.search(line_lower)
        if m_term:
            term = m_term.group(1).lower()
            self._emit_event(self._build_event(
                timestamp=ts,
                category="SURVEILLANCE",
                subcategory=term,
                file_path=file_rel,
                line_offset=line_num,
                raw_line=line_stripped,
                normalized_line=line_lower,
                severity="HIGH",
                iocs={"term": term},
                file_sha256=file_sha,
                file_entropy=file_ent,
            ))

        for m in URL_RE.finditer(line_stripped):
            url = m.group(1)
            self._emit_event(self._build_event(
                timestamp=ts,
                category="NETWORK",
                subcategory="URL",
                file_path=file_rel,
                line_offset=line_num,
                raw_line=line_stripped,
                normalized_line=line_lower,
                severity="MEDIUM",
                iocs={"url": url},
                file_sha256=file_sha,
                file_entropy=file_ent,
            ))

        for m in DOMAIN_RE.finditer(line_stripped):
            dom = normalize_domain(m.group(0))
            if dom:
                self._emit_event(self._build_event(
                    timestamp=ts,
                    category="NETWORK",
                    subcategory="DOMAIN",
                    file_path=file_rel,
                    line_offset=line_num,
                    raw_line=line_stripped,
                    normalized_line=line_lower,
                    severity="MEDIUM",
                    iocs={"domain": dom},
                    file_sha256=file_sha,
                    file_entropy=file_ent,
                ))

        for m in IPV4_RE.finditer(line_stripped):
            ipn = normalize_ip(m.group(0))
            if ipn:
                self._emit_event(self._build_event(
                    timestamp=ts,
                    category="NETWORK",
                    subcategory="IP",
                    file_path=file_rel,
                    line_offset=line_num,
                    raw_line=line_stripped,
                    normalized_line=line_lower,
                    severity="MEDIUM",
                    iocs={"ip": ipn},
                    file_sha256=file_sha,
                    file_entropy=file_ent,
                ))

        for m in IPV6_RE.finditer(line_stripped):
            ipn = normalize_ip(m.group(0))
            if ipn and ":" in ipn:
                self._emit_event(self._build_event(
                    timestamp=ts,
                    category="NETWORK",
                    subcategory="IPV6",
                    file_path=file_rel,
                    line_offset=line_num,
                    raw_line=line_stripped,
                    normalized_line=line_lower,
                    severity="MEDIUM",
                    iocs={"ip": ipn},
                    file_sha256=file_sha,
                    file_entropy=file_ent,
                ))

        for m in MAC_RE.finditer(line_stripped):
            mac = m.group(0).lower().replace("-", ":")
            self._emit_event(self._build_event(
                timestamp=ts,
                category="NETWORK",
                subcategory="MAC",
                file_path=file_rel,
                line_offset=line_num,
                raw_line=line_stripped,
                normalized_line=line_lower,
                severity="LOW",
                iocs={"mac": mac},
                file_sha256=file_sha,
                file_entropy=file_ent,
            ))

        for m in IMEI_RE.finditer(line_stripped):
            val = m.group(1)
            candidate = val[:15]
            if candidate.isdigit() and luhn_checksum_ok(candidate):
                self._emit_event(self._build_event(
                    timestamp=ts,
                    category="CRITICAL",
                    subcategory="IMEI",
                    file_path=file_rel,
                    line_offset=line_num,
                    raw_line=line_stripped,
                    normalized_line=line_lower,
                    severity="CRITICAL",
                    iocs={"imei": candidate},
                    file_sha256=file_sha,
                    file_entropy=file_ent,
                ))

        if SERIAL_HINT_RE.search(line_stripped):
            for m in IMEI_BARE_RE.finditer(line_stripped):
                candidate = m.group(1)
                if luhn_checksum_ok(candidate):
                    self._emit_event(self._build_event(
                        timestamp=ts,
                        category="CRITICAL",
                        subcategory="IMEI_BARE",
                        file_path=file_rel,
                        line_offset=line_num,
                        raw_line=line_stripped,
                        normalized_line=line_lower,
                        severity="CRITICAL",
                        iocs={"imei": candidate},
                        file_sha256=file_sha,
                        file_entropy=file_ent,
                    ))

        for m in IMSI_RE.finditer(line_stripped):
            val = m.group(1)
            if val.isdigit() and 14 <= len(val) <= 16:
                self._emit_event(self._build_event(
                    timestamp=ts,
                    category="SENSITIVE",
                    subcategory="IMSI",
                    file_path=file_rel,
                    line_offset=line_num,
                    raw_line=line_stripped,
                    normalized_line=line_lower,
                    severity="HIGH",
                    iocs={"imsi": val},
                    file_sha256=file_sha,
                    file_entropy=file_ent,
                ))

        for m in ICCID_RE.finditer(line_stripped):
            digits = re.sub(r"\D", "", m.group(1))
            if digits.isdigit() and 18 <= len(digits) <= 22:
                sev = "HIGH" if luhn_checksum_ok(digits[:19]) else "MEDIUM"
                self._emit_event(self._build_event(
                    timestamp=ts,
                    category="SENSITIVE",
                    subcategory="ICCID",
                    file_path=file_rel,
                    line_offset=line_num,
                    raw_line=line_stripped,
                    normalized_line=line_lower,
                    severity=sev,
                    iocs={"iccid": digits},
                    file_sha256=file_sha,
                    file_entropy=file_ent,
                ))

    def _parse_plist_file(self, path: Path, file_rel: str, file_sha: str, file_ent: float) -> None:
        if plistlib is None:
            return
        try:
            with open(path, "rb") as f:
                data = f.read()
            obj = plistlib.loads(data)
            keys: List[str] = []
            if isinstance(obj, dict):
                keys = list(obj.keys())
            self._emit_event(self._build_event(
                timestamp=None,
                category="CONFIG",
                subcategory="PLIST",
                file_path=file_rel,
                line_offset=0,
                raw_line="",
                normalized_line=json.dumps(obj, ensure_ascii=False, sort_keys=True),
                severity="MEDIUM",
                iocs={"plist_keys": keys},
                file_sha256=file_sha,
                file_entropy=file_ent,
            ))
        except Exception:
            return

    def _parse_sqlite_file(self, path: Path, file_rel: str, file_sha: str, file_ent: float) -> None:
        conn = None
        try:
            uri = f"file:{path.as_posix()}?mode=ro"
            conn = sqlite3.connect(uri, uri=True)
            conn.row_factory = sqlite3.Row
            tables = [row["name"] for row in conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%';")]
            row_counts: Dict[str, int] = {}
            for t in tables[:200]:
                try:
                    q = 'SELECT COUNT(*) AS cnt FROM "' + t.replace('"', '""') + '"'
                    row = conn.execute(q).fetchone()
                    if row is not None and "cnt" in row.keys():
                        row_counts[t] = int(row["cnt"])
                except Exception:
                    continue
            result = {"tables": tables, "row_counts": row_counts}
            self._emit_event(self._build_event(
                timestamp=None,
                category="DATABASE",
                subcategory=path.name,
                file_path=file_rel,
                line_offset=0,
                raw_line="",
                normalized_line=json.dumps(result, ensure_ascii=False, sort_keys=True),
                severity="HIGH" if tables else "MEDIUM",
                iocs={"tables": tables},
                file_sha256=file_sha,
                file_entropy=file_ent,
            ))
        except Exception:
            return
        finally:
            try:
                if conn is not None:
                    conn.close()
            except Exception:
                pass

    def _scan_binary_strings(self, path: Path, file_rel: str, file_sha: str, file_ent: float) -> None:
        try:
            max_bytes = self.max_binary_strings_bytes
            read_bytes = 0
            with open(path, "rb") as f:
                while True:
                    if max_bytes is not None and read_bytes >= max_bytes:
                        break
                    chunk = f.read(4 * 1024 * 1024)
                    if not chunk:
                        break
                    read_bytes += len(chunk)
                    for m in PRINTABLE_ASCII_RE.finditer(chunk):
                        try:
                            s = m.group(0).decode("utf-8", errors="replace")
                        except Exception:
                            continue
                        s_l = s.lower()
                        ts = extract_timestamp(s)
                        tm = TERMS_RE.search(s_l)
                        if tm:
                            term = tm.group(1).lower()
                            self._emit_event(self._build_event(
                                timestamp=ts,
                                category="SURVEILLANCE",
                                subcategory=f"BINSTR_{term}",
                                file_path=file_rel,
                                line_offset=0,
                                raw_line=s,
                                normalized_line=s_l,
                                severity="MEDIUM",
                                iocs={"term": term},
                                file_sha256=file_sha,
                                file_entropy=file_ent,
                            ))
                        for dm in DOMAIN_RE.finditer(s):
                            dom = normalize_domain(dm.group(0))
                            if dom:
                                self._emit_event(self._build_event(
                                    timestamp=ts,
                                    category="NETWORK",
                                    subcategory="BINSTR_DOMAIN",
                                    file_path=file_rel,
                                    line_offset=0,
                                    raw_line=s,
                                    normalized_line=s_l,
                                    severity="LOW",
                                    iocs={"domain": dom},
                                    file_sha256=file_sha,
                                    file_entropy=file_ent,
                                ))
        except Exception:
            return

    def process_file(self, path: Path) -> None:
        if self._stop.is_set():
            return
        try:
            if not self.follow_symlinks and path.is_symlink():
                return
        except Exception:
            return
        try:
            st = path.stat()
        except Exception:
            return
        size_bytes = int(st.st_size)
        created, modified, accessed = self._stat_times(st)
        file_rel = self._safe_rel(path)
        file_kind, _ = guess_file_type(path)

        hasher = FileHasher()
        ent_calc = EntropyCalculator()

        try:
            with open(path, "rb") as f:
                while True:
                    chunk = f.read(1024 * 1024)
                    if not chunk:
                        break
                    hasher.update(chunk)
                    ent_calc.update(chunk)
        except Exception:
            return

        file_sha = hasher.hexdigest()
        file_ent = ent_calc.entropy()
        mime_type = self._classify_mime(file_ent)

        meta = FileMetadata(
            path=file_rel,
            size_bytes=size_bytes,
            sha256=file_sha,
            entropy=file_ent,
            mime_type=mime_type,
            file_type=file_kind,
            created=created,
            modified=modified,
            accessed=accessed,
        )
        self.inventory_writer.write_meta(meta)

        if file_kind == "plist":
            self._parse_plist_file(path, file_rel, file_sha, file_ent)

        if file_kind == "sqlite":
            self._parse_sqlite_file(path, file_rel, file_sha, file_ent)

        is_textish = (mime_type == "text") or (file_kind in {"json", "text"})
        if is_textish:
            try:
                with open(path, "rb") as f:
                    for i, line in enumerate(TextLineStream(f, encoding="utf-8")):
                        self._scan_text_line(file_rel, file_sha, file_ent, i, line)
            except Exception:
                try:
                    with open(path, "rb") as f:
                        for i, line in enumerate(TextLineStream(f, encoding="latin-1")):
                            self._scan_text_line(file_rel, file_sha, file_ent, i, line)
                except Exception:
                    pass
        else:
            if self.scan_binary_strings:
                self._scan_binary_strings(path, file_rel, file_sha, file_ent)

        with self._files_lock:
            self._files_scanned += 1

    def iter_files(self) -> Iterable[Path]:
        for p in self.root.rglob("*"):
            try:
                if p.is_file():
                    yield p
            except Exception:
                continue

    def scan(self, max_files: Optional[int]) -> None:
        q_files: "queue.Queue[Optional[Path]]" = queue.Queue(maxsize=max(1, self.max_workers * 8))
        errors: "queue.Queue[str]" = queue.Queue()
        produced = 0

        def worker() -> None:
            while True:
                item = q_files.get()
                if item is None:
                    q_files.task_done()
                    return
                try:
                    self.process_file(item)
                except Exception as e:
                    try:
                        errors.put(f"{self._safe_rel(item)}: {e}")
                    except Exception:
                        pass
                finally:
                    q_files.task_done()

        threads = []
        for _ in range(self.max_workers):
            t = threading.Thread(target=worker, daemon=True)
            t.start()
            threads.append(t)

        try:
            for p in self.iter_files():
                if self._stop.is_set():
                    break
                if max_files is not None and produced >= max_files:
                    break
                q_files.put(p)
                produced += 1
        finally:
            for _ in threads:
                q_files.put(None)
            q_files.join()
            for t in threads:
                try:
                    t.join()
                except Exception:
                    pass

        err_list: List[str] = []
        while True:
            try:
                err_list.append(errors.get_nowait())
            except Exception:
                break
        if err_list:
            write_json(self.output / "scan_errors.json", err_list)

    def finalize(self) -> None:
        elapsed = time.time() - self._start_time
        ioc_list = self.iocs.to_list()
        write_json(self.output / "iocs.json", ioc_list)
        summary = {
            "timestamp": datetime.now().isoformat(),
            "root": str(self.root),
            "output": str(self.output),
            "elapsed_seconds": elapsed,
            "total_files": self.inventory_writer.total_files,
            "total_events": self.events_writer.total_events,
            "events_by_category": self.events_writer.counts,
            "ioc_total": len(ioc_list),
        }
        write_json(self.output / "executive_summary.json", summary)

        imei_iocs = [r for r in ioc_list if r.get("type") == "imei"]
        hu = []
        hu.append(f"IMEI MEGFIGYELÉSI ELEMZÉS - {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
        hu.append("")
        hu.append(f"ÖSSZES FÁJL: {self.inventory_writer.total_files}")
        hu.append(f"ESEMÉNYEK: {self.events_writer.total_events}")
        hu.append(f"IOC ÖSSZESEN: {len(ioc_list)}")
        hu.append(f"IMEI TALÁLATOK: {len(imei_iocs)}")
        hu.append("")
        if imei_iocs:
            hu.append("🚨 IMEI TALÁLATOK (IOC):")
            for r in imei_iocs:
                files = r.get("files", [])
                f0 = files[0] if files else ""
                hu.append(f"- {r.get('value')} | count={r.get('count')} | first_file={f0}")
        else:
            hu.append("✅ IMEI találat nem került kiemelésre (Luhn-valid IMEI).")
        write_txt(self.output / "imei_summary_hu.txt", "\n".join(hu))

        self.events_writer.close()
        self.inventory_writer.close()

def is_within_directory(directory: Path, target: Path) -> bool:
    try:
        directory = directory.resolve()
        target = target.resolve()
        return str(target).startswith(str(directory) + os.sep) or target == directory
    except Exception:
        return False

def safe_extract_tar(tar: tarfile.TarFile, path: Path) -> None:
    safe_mkdir(path)
    for member in tar.getmembers():
        member_path = path / member.name
        if not is_within_directory(path, member_path):
            raise RuntimeError("Unsafe tar path traversal detected")
    tar.extractall(path)

def find_latest_candidate(base: Path) -> Optional[Path]:
    candidates: List[Path] = []
    for p in base.rglob("*"):
        try:
            if p.is_dir():
                name = p.name.lower()
                if "sysdiagnose" in name or name.startswith("extract") or "diagnose" in name:
                    candidates.append(p)
        except Exception:
            continue
    if not candidates:
        return None
    candidates.sort(key=lambda x: x.stat().st_mtime, reverse=True)
    return candidates[0]

def find_latest_tar_gz(base: Path) -> Optional[Path]:
    tars: List[Path] = []
    for p in base.rglob("*.tar.gz"):
        try:
            if p.is_file():
                tars.append(p)
        except Exception:
            continue
    for p in base.rglob("*.tgz"):
        try:
            if p.is_file():
                tars.append(p)
        except Exception:
            continue
    if not tars:
        return None
    tars.sort(key=lambda x: x.stat().st_mtime, reverse=True)
    return tars[0]

def prepare_root(input_path: Optional[str], work_dir: Path) -> Path:
    base = Path(input_path).expanduser().resolve() if input_path else Path.cwd().resolve()
    if base.is_file() and base.name.lower().endswith((".tar.gz", ".tgz")):
        extract_dir = work_dir / f"extract_{int(time.time())}"
        with tarfile.open(base, "r:*") as tar:
            safe_extract_tar(tar, extract_dir)
        cand = find_latest_candidate(extract_dir)
        return cand if cand is not None else extract_dir
    if base.is_dir():
        cand = find_latest_candidate(base)
        if cand is not None:
            return cand
        tar_path = find_latest_tar_gz(base)
        if tar_path is not None:
            extract_dir = work_dir / f"extract_{int(time.time())}"
            with tarfile.open(tar_path, "r:*") as tar:
                safe_extract_tar(tar, extract_dir)
            cand2 = find_latest_candidate(extract_dir)
            return cand2 if cand2 is not None else extract_dir
        return base
    raise RuntimeError("Input path not found")

def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser()
    p.add_argument("--input", type=str, default=None)
    p.add_argument("--output", type=str, default=None)
    p.add_argument("--workers", type=int, default=max(4, (os.cpu_count() or 8)))
    p.add_argument("--max-files", type=int, default=None)
    p.add_argument("--follow-symlinks", action="store_true")
    p.add_argument("--scan-binary-strings", action="store_true")
    p.add_argument("--max-binary-strings-bytes", type=int, default=None)
    return p.parse_args()

def main() -> None:
    args = parse_args()
    base_out = Path(args.output).expanduser().resolve() if args.output else Path.cwd().resolve() / f"FORENSIC_REPORT_{now_ts()}"
    safe_mkdir(base_out)
    work_dir = base_out / "_work"
    safe_mkdir(work_dir)
    root = prepare_root(args.input, work_dir)

    analyzer = ForensicAnalyzer(
        root_path=root,
        output_path=base_out,
        max_workers=max(1, int(args.workers)),
        follow_symlinks=bool(args.follow_symlinks),
        scan_binary_strings=bool(args.scan_binary_strings),
        max_binary_strings_bytes=args.max_binary_strings_bytes,
    )
    try:
        analyzer.scan(args.max_files)
    finally:
        analyzer.finalize()
        try:
            shutil.rmtree(work_dir, ignore_errors=True)
        except Exception:
            pass

if __name__ == "__main__":
    main()


